      out.append(mt | 24)
      out.append(UInt8(n))
    } else if n < 0x1_0000 {
      out.append(mt | 25)
      out.append(UInt8(n >> 8))
      out.append(UInt8(n & 0xff))
    } else if n < 0x1_0000_0000 {
      out.append(mt | 26)
      var i = 24
      while i >= 0 {
        out.append(UInt8((n >> UInt64(i)) & 0xff))
        i -= 8
      }
    } else {
      out.append(mt | 27)
      var i = 56
      while i >= 0 {
        out.append(UInt8((n >> UInt64(i)) & 0xff))
        i -= 8
      }
    }
