    guard pos < b.count, b.count - pos - 1 >= width else { throw CsilCborError.malformed }
    switch low {
    case 24:
      let v = UInt64(b[pos + 1])
      pos += 2
      return v
    case 25:
      let v = (UInt64(b[pos + 1]) << 8) | UInt64(b[pos + 2])
      pos += 3
      return v
    case 26:
      var v: UInt64 = 0
