public struct RpErrorRefusal: Swift.Error {
  public let value: RpError
  public init(value: RpError) { self.value = value }
}

/// Runs the handler and encodes the reply arm it chose. A thrown error, from the
/// handler or from a reply value that cannot be encoded, means there is no typed
/// reply: answer with transport status 6 (internal).
public func encodeRpSignRequestReply(
  _ handler: () throws -> RpSignResponse
) throws -> (variant: String, payload: [UInt8]) {
  do {
    let value = try handler()
    return ("RpSignResponse", CsilCbor.encode(try value.toCborValue()))
  } catch let refusal as RpErrorRefusal {
    return ("RpError", CsilCbor.encode(try refusal.value.toCborValue()))
  }
}

/// Runs the handler and encodes the reply arm it chose. A thrown error, from the
