}

public func resolveRpcReply(
  service: String,
  op: String,
  variant: String?,
  payload: [UInt8]
) throws -> [UInt8] {
  if service == "Rp" && op == "sign-request" {
    switch variant {
    case "RpSignResponse": return payload
    case "RpError": throw RpErrorRefusal(value: try RpError(cborValue: CsilCbor.decode(payload)))
    default: throw CsilCborError.typeMismatch
    }
  }
  if service == "Rp" && op == "decrypt-token" {
    switch variant {
    case "RpDecryptResponse": return payload
    case "RpError": throw RpErrorRefusal(value: try RpError(cborValue: CsilCbor.decode(payload)))
    default: throw CsilCborError.typeMismatch
    }
  }
  if service == "Rp" && op == "verify-assertion" {
    switch variant {
    case "RpVerifyResponse": return payload
    case "RpError": throw RpErrorRefusal(value: try RpError(cborValue: CsilCbor.decode(payload)))
    default: throw CsilCborError.typeMismatch
    }
  }
  if service == "Rp" && op == "userinfo-fetch" {
    switch variant {
    case "UserInfo": return payload
    case "RpError": throw RpErrorRefusal(value: try RpError(cborValue: CsilCbor.decode(payload)))
    default: throw CsilCborError.typeMismatch
    }
  }
  return payload
}
